<template>
  <section class="mcp-panel">
    <div class="mcp-hero"><div><span class="mcp-eyebrow">能力接入 / 其他 AI 工具</span><h2>外部 AI 接入</h2><p>将云枢的查询、分析和业务操作能力发布给 WorkBuddy 等其他 AI 工具，让用户在原有对话入口中直接完成云枢工作。</p></div><el-tag :type="statusType" effect="plain" round>{{ statusLabel }}</el-tag></div>
    <el-alert class="mcp-boundary" type="info" show-icon :closable="false"><template #title>接入边界</template>云枢访问地址来自 CPClaw 已配置的云枢环境，不需要在此重复填写。使用者账号和密码在接入工具一侧配置，CPClaw 不保存终端凭据；生产接入还必须同时提供企业租户标识和用户身份签名。</el-alert>

    <el-card class="mcp-card" shadow="never"><template #header><div class="mcp-card-title"><strong>能力发布</strong><small>发布后，其他 AI 工具可以直接连接 CPClaw 使用云枢能力，无需安装脚本或提供 CPClaw 安装目录。</small></div></template><el-form label-position="top" class="mcp-form"><el-form-item label="接入标识"><el-input v-model="form.installationId" readonly><template #append><el-button @click="copyInstallationId">复制</el-button></template></el-input></el-form-item><el-form-item label="终端名称"><el-input v-model="form.displayName" readonly /></el-form-item><el-form-item label="云枢环境"><div class="environment-state"><span :class="['environment-dot',{ready:installation?.environmentConfigured}]" /><span>{{ installation?.environmentConfigured ? '已使用 CPClaw 配置的云枢环境' : 'CPClaw 尚未配置云枢环境地址' }}</span></div></el-form-item><el-form-item label="接入配置片段"><el-input :model-value="configText" type="textarea" :rows="8" readonly /></el-form-item><div class="mcp-actions"><el-button type="primary" :loading="publishing" :disabled="!installation?.environmentConfigured" @click="publish"><el-icon><CircleCheck /></el-icon>{{ isEnabled ? '更新发布配置' : '发布能力' }}</el-button><el-button v-if="isEnabled" text type="danger" :loading="disabling" @click="disable">停用接入</el-button></div><el-alert v-if="message" :type="messageType" show-icon :closable="false" :title="message" /></el-form></el-card>

    <el-card class="mcp-card" shadow="never"><template #header><div class="mcp-card-title"><strong>接入说明</strong><small>当前联调阶段使用云枢账号密码；生产环境还会校验租户标识和接入工具的用户身份签名。</small></div></template><ol class="mcp-guide"><li><span>1</span><div><strong>管理员发布能力</strong><small>确认 CPClaw 已配置云枢环境，然后复制接入配置片段。</small></div></li><li><span>2</span><div><strong>在 AI 工具中完成接入</strong><small>将配置片段粘贴到 WorkBuddy 或其他兼容工具的连接设置中，并由部署方为工具配置企业租户、用户标识、时间戳和 HMAC 签名。</small></div></li><li><span>3</span><div><strong>直接使用云枢能力</strong><small>用户在 AI 工具中直接发起查询、分析或业务操作，CPClaw 负责能力路由、租户与权限校验和脱敏审计。</small></div></li></ol></el-card>

    <el-card class="mcp-card" shadow="never"><template #header><div class="mcp-card-title"><strong>能力清单</strong><small>未验证的写操作不会被自动执行，涉及数据变更时会先请求确认。</small></div></template><div class="mcp-capabilities"><div v-for="capability in installation?.capabilities ?? []" :key="capability.name" class="mcp-capability"><span class="mcp-capability-dot" :class="`is-${capability.status}`" /><div><strong>{{ capability.name }}</strong><small>{{ capability.rule }}</small></div><el-tag size="small" effect="plain">{{ capabilityLabel(capability.status) }}</el-tag></div></div></el-card>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { CircleCheck } from '@element-plus/icons-vue'
import { disableCloudPivotMcp, enableCloudPivotMcp, getCloudPivotMcp } from '../../services/mcpApi'
import type { McpCloudPivotBindingRequest, McpCloudPivotInstallation } from '../../types/mcp'

const installation = ref<McpCloudPivotInstallation>(); const publishing = ref(false); const disabling = ref(false); const message = ref(''); const messageType = ref<'success' | 'warning' | 'info' | 'error'>('info')
const form = reactive<McpCloudPivotBindingRequest>({ installationId: '', displayName: '' })
const isEnabled = computed(() => installation.value?.status === 'ENABLED'); const statusLabel = computed(() => installation.value?.status === 'ENABLED' ? '已发布' : installation.value?.status === 'DISABLED' ? '已停用' : '待发布'); const statusType = computed(() => installation.value?.status === 'ENABLED' ? 'success' : installation.value?.status === 'DISABLED' ? 'info' : 'warning'); const configText = computed(() => JSON.stringify({ CloudPivotMCP: installation.value?.mcpClientConfig ?? {} }, null, 2))
onMounted(() => { void load() })
async function load() { try { installation.value = await getCloudPivotMcp(); Object.assign(form, { installationId: installation.value.installationId, displayName: installation.value.displayName }) } catch (error) { setMessage(error, '加载外部接入状态失败', 'error') } }
async function publish() { publishing.value = true; try { installation.value = await enableCloudPivotMcp({ ...form }); setMessage('能力已发布。请将配置片段提供给目标 AI 工具的使用者。', 'success') } catch (error) { setMessage(error, '发布能力失败', 'error') } finally { publishing.value = false } }
async function disable() { disabling.value = true; try { installation.value = await disableCloudPivotMcp(form.installationId); setMessage('外部接入已停用。', 'info') } catch (error) { setMessage(error, '停用外部接入失败', 'error') } finally { disabling.value = false } }
async function copyInstallationId() { await navigator.clipboard?.writeText(form.installationId); ElMessage.success('安装标识已复制') }
function setMessage(error: unknown, fallback: string, type: 'success' | 'warning' | 'info' | 'error') { messageType.value = type; message.value = error instanceof Error && error.message ? error.message : fallback }
function capabilityLabel(status: string) { return status === 'enabled' ? '可用' : status === 'verified-readonly' ? '只读已验证' : status === 'confirmation-required' ? '需确认' : status }
</script>

<style scoped>
.mcp-panel{display:grid;max-width:980px;gap:16px}.mcp-hero{display:flex;align-items:flex-start;justify-content:space-between;gap:24px}.mcp-eyebrow{color:var(--settings-brand);font-size:11px;font-weight:600;letter-spacing:.08em}.mcp-hero h2{margin:8px 0 7px;font-size:clamp(25px,3vw,34px);font-weight:650;letter-spacing:-.025em}.mcp-hero p{max-width:760px;margin:0;color:var(--settings-secondary);font-size:13.5px;line-height:1.65}.mcp-boundary{align-items:flex-start;border-radius:10px}.mcp-card{border-color:var(--settings-line);border-radius:var(--settings-radius);background:var(--settings-surface);box-shadow:none}.mcp-card :deep(.el-card__header){padding:18px 22px;border-color:var(--settings-line)}.mcp-card :deep(.el-card__body){padding:22px}.mcp-card-title{display:grid;gap:4px}.mcp-card-title small,.mcp-guide small{color:var(--settings-secondary);font-size:12px;line-height:1.5}.mcp-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.mcp-form .el-form-item:nth-child(3),.mcp-form .el-form-item:nth-child(4),.mcp-actions,.mcp-form .el-alert{grid-column:1/-1}.mcp-form :deep(.el-textarea__inner){font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12px;line-height:1.5}.environment-state{display:flex;min-height:42px;align-items:center;gap:9px;padding:0 12px;border:1px solid var(--settings-line);border-radius:8px;color:var(--settings-secondary);font-size:13px}.environment-dot,.mcp-capability-dot{width:8px;height:8px;border-radius:50%;background:#f59e0b}.environment-dot.ready,.mcp-capability-dot.is-enabled{background:#22c55e}.mcp-capability-dot.is-verified-readonly{background:#4f6ef7}.mcp-actions{display:flex;flex-wrap:wrap;gap:10px;padding-top:18px;border-top:1px solid var(--settings-line)}.mcp-guide{display:grid;gap:2px;margin:0;padding:0;list-style:none}.mcp-guide li{display:grid;grid-template-columns:24px minmax(0,1fr);gap:10px;padding:11px 0;border-bottom:1px solid var(--settings-line)}.mcp-guide li:last-child{border-bottom:0}.mcp-guide li>span{color:var(--settings-tertiary);font-size:11px;font-weight:600}.mcp-guide div,.mcp-capability div{display:grid;gap:3px}.mcp-guide strong,.mcp-capability strong{font-size:13px}.mcp-guide code{padding:1px 4px;border-radius:4px;background:var(--settings-surface-soft);font-size:11px}.mcp-capabilities{display:grid;gap:2px}.mcp-capability{display:grid;grid-template-columns:10px minmax(0,1fr) auto;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--settings-line)}.mcp-capability:last-child{border-bottom:0}.mcp-capability small{color:var(--settings-secondary);font-size:12px;line-height:1.45}@media(max-width:620px){.mcp-hero{flex-direction:column;gap:12px}.mcp-form{grid-template-columns:1fr}.mcp-form .el-form-item:nth-child(3),.mcp-form .el-form-item:nth-child(4),.mcp-actions,.mcp-form .el-alert{grid-column:auto}.mcp-actions{align-items:stretch;flex-direction:column}.mcp-actions .el-button{width:100%;margin-left:0}}
</style>
